with u as (
  update employees set status = 'sent_back' where id = $1::uuid returning id
)
insert into automation_log (employee_id, workflow, step, status, detail)
select id, 'wf1', 'hr_approval', 'sent_back', 'HR sent the request back. Nothing was sent.' from u
returning id;

with done as (
  update onboarding_tasks set completed_at = now(), completed_by = 'wf1'
  where employee_id = $1::uuid and task_key = 'welcome_email' and completed_at is null
  returning 1
)
select reserve_laptop($1::uuid, $2) as laptop;

